import { ReactNode } from 'react';
import { Annotation } from './annotations.js';
/** @internal */
export interface MarkerProps {
    /** Annotation data point. */
    data: Annotation;
    /** Annotation markers color (hex, rgba, token). */
    color?: string;
    /** Priority of annotation. */
    priority?: number;
    /** Annotation marker character (letter/emoji/icon/glyph or Unicode character). */
    symbol?: ReactNode;
    /** Flag to hide a marker */
    hidden?: boolean;
}
export interface CircleMarkerProps {
    x: number;
    data: Annotation[];
    color: string;
}
export interface PillMarkerProps extends CircleMarkerProps {
    width: number;
}
